return [{ json: {
  niche: 'personal finance for new grads',
  topic: 'What to do with your first paycheck',
  target_length_min: 6,
  audience: 'US early-career, 22-28'
} }];

const j = $input.first().json;
const e = [];
if (!j.niche || !j.topic) e.push('niche and topic are required');
if (!Number.isFinite(j.target_length_min) || j.target_length_min < 1 || j.target_length_min > 30) e.push('target_length_min must be 1-30');
if (e.length) throw new Error('Invalid input: ' + e.join('; '));
return [{ json: j }];

const raw = $json && $json.content && $json.content[0] && $json.content[0].text;
if (!raw) throw new Error('Anthropic response missing content[0].text');
let s;
try { s = JSON.parse(raw); } catch (e) { throw new Error('Model did not return valid JSON: ' + raw.slice(0,200)); }
const missing = [];
if (!s.hook || !s.hook.trim()) missing.push('hook');
if (!Array.isArray(s.open_loops) || !s.open_loops.length) missing.push('open_loops');
if (!Array.isArray(s.scenes) || !s.scenes.length) missing.push('scenes');
else s.scenes.forEach((sc, i) => { if (!sc.spoken) missing.push('scenes['+i+'].spoken'); if (!sc.visual_text) missing.push('scenes['+i+'].visual_text'); if (!sc.pause_markers) missing.push('scenes['+i+'].pause_markers'); });
if (!s.soft_cta) missing.push('soft_cta');
if (!Array.isArray(s.titles) || !s.titles.length) missing.push('titles');
if (missing.length) throw new Error('Script missing required taught elements: ' + missing.join(', '));
return [{ json: { script: s, next: 'MANUAL_HANDOFF: 11 Labs voiceover -> CapCut edit + Pexels stock -> upload to YouTube (all require human/tools; not automated here)' } }];

const sourceId="DYWFQKAPgmF";
const sourceUrl="https://www.instagram.com/raycfu/reel/DYWFQKAPgmF/";
const variant='USER_STACK';
const seen=new Set();
const hash=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(16).padStart(8,'0');};
return $input.all().map(({json:j},i)=>{
  const recordKey=String(j.row_id||j.clip_id||j.note_id||j.fileName||j.output_path||j.title||i);
  const idempotencyKey=hash(sourceId+'|'+recordKey);
  if(seen.has(idempotencyKey)) throw new Error('Duplicate output in one execution: '+idempotencyKey);
  seen.add(idempotencyKey);
  return {json:{...j,source_provenance:{source_id:sourceId,source_url:sourceUrl,variant},idempotency_key:idempotencyKey,review_status:'needs_human_review',review_notes:Array.isArray(j.review_notes)?j.review_notes:[],external_actions_enabled:false}};
});
